import{_ as o,o as d,c as i,a3 as r,j as a,a as t,t as n}from"./chunks/framework.DACwFHq9.js";const m=JSON.parse('{"title":"知识资料库快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/tools/knowledge-base/index.md","filePath":"user-guide/tools/knowledge-base/index.md","lastUpdated":1785036254000}'),s={name:"user-guide/tools/knowledge-base/index.md"};function h(l,e,p,u,c,b){return d(),i("div",null,[e[4]||(e[4]=r('<h1 id="知识资料库快速上手" tabindex="-1">知识资料库快速上手 <a class="header-anchor" href="#知识资料库快速上手" aria-label="Permalink to &quot;知识资料库快速上手&quot;">​</a></h1><p>知识资料库用于导入 PDF、DOCX、HTML、Markdown、文本和代码文件，并把它们转换为带来源信息的文档分块。它与“思绪”是两个独立领域：知识资料库管理可引用的 document/chunk/source，思绪管理完整语义条目、标签和联想召回。</p><h2 id="处理旧知识库数据迁移" tabindex="-1">处理旧知识库数据迁移 <a class="header-anchor" href="#处理旧知识库数据迁移" aria-label="Permalink to &quot;处理旧知识库数据迁移&quot;">​</a></h2><p>升级后如果检测到旧 <code>knowledge/bases</code>、<code>vectors</code> 或 <code>tag_pool</code> 目录，应用只会显示待迁移提示，不会在启动时自动改写用户数据。可以从版本升级引导、“设置 → 关于 → 继续升级事项”或知识资料库顶部提示进入迁移流程。</p><p>迁移流程会依次展示旧数据规模、可保留字段、待重建内容和备份提示。只有同时确认备份与写入风险后，应用才会把旧 Recall 集合写入新的 SQLite 存储。迁移报告会分别显示主数据、向量、待重建项和问题明细。</p><p>旧目录默认保留。只有主数据和向量均完整通过、没有待重建向量和未解决问题时，流程才提供独立清理选项；清理前还需要再次输入 <code>DELETE</code> 确认。迁移中断或主数据部分成功时，可以关闭流程稍后继续，同一来源指纹不会重复导入已完成内容。</p><h2 id="创建资料库" tabindex="-1">创建资料库 <a class="header-anchor" href="#创建资料库" aria-label="Permalink to &quot;创建资料库&quot;">​</a></h2><ol><li>打开“知识资料库”。</li><li>点击侧栏右上角的加号。</li><li>输入资料库名称，可补充用途说明。</li><li>点击“创建”。</li></ol><p>创建成功后会自动进入新资料库。</p><h2 id="导入文档" tabindex="-1">导入文档 <a class="header-anchor" href="#导入文档" aria-label="Permalink to &quot;导入文档&quot;">​</a></h2><p>点击顶部“导入文档”，可一次选择多个支持的文件。界面会分别显示解析进度和写入进度。</p><ul><li>单个文件失败不会中断整批导入。</li><li>成功项会立即保留。</li><li>失败数量会在工作台顶部汇总，可重新选择失败文件重试。</li><li>再次导入相同来源路径会更新原文档及其分块。</li></ul><h2 id="检查文档分块" tabindex="-1">检查文档分块 <a class="header-anchor" href="#检查文档分块" aria-label="Permalink to &quot;检查文档分块&quot;">​</a></h2><p>“文档”模式左侧显示当前资料库的文档列表。选择文档后，右侧展示实际进入索引的分块、章节标题和分块编号。</p><p>这不是原文件预览，而是检索引擎实际读取的文本。检索效果异常时，应先在这里检查解析和切分结果。</p><h2 id="构建语义索引" tabindex="-1">构建语义索引 <a class="header-anchor" href="#构建语义索引" aria-label="Permalink to &quot;构建语义索引&quot;">​</a></h2><p>文档导入后，关键词索引立即可用。需要语义或混合检索时：</p><ol><li>点击顶部“语义索引”。</li><li>选择一个已启用且支持 Embedding 的模型。</li><li>点击“开始构建”。</li><li>等待分块覆盖率达到 100%。</li></ol><p>切换模型会要求确认。界面按当前模型显示向量覆盖率；已写入批次会被保留，失败后可以重新构建。</p><h2 id="测试检索" tabindex="-1">测试检索 <a class="header-anchor" href="#测试检索" aria-label="Permalink to &quot;测试检索&quot;">​</a></h2><p>切换到“检索测试”模式，输入查询并选择策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>说明</th></tr></thead><tbody><tr><td>自动</td><td>有可用查询向量时使用混合检索，否则退化为关键词检索</td></tr><tr><td>关键词</td><td>只使用 BM25，导入后立即可用</td></tr><tr><td>混合</td><td>融合关键词、向量和相邻分块信号</td></tr><tr><td>语义</td><td>只使用当前模型的向量</td></tr></tbody></table><p>结果详情显示来源路径、章节、分块编号和命中信号。点击“查看文档”可回到文档模式并定位来源。</p><h2 id="在-agent-中使用" tabindex="-1">在 Agent 中使用 <a class="header-anchor" href="#在-agent-中使用" aria-label="Permalink to &quot;在 Agent 中使用&quot;">​</a></h2>',24)),a("p",null,[e[0]||(e[0]=t("Agent 通过稳定的资料库 ID 获得 Knowledge 资料访问权限。授权本身不会自动检索，也不会自动向每轮上下文注入目录；需要常驻目录时，可在合适的预设消息位置放置 ",-1)),a("code",null,n(l.knowledge_list),1),e[1]||(e[1]=t("。具体权限和调用方式见 ",-1)),e[2]||(e[2]=a("a",{href:"./agent-integration"},"Agent 集成",-1)),e[3]||(e[3]=t("。",-1))])])}const f=o(s,[["render",h]]);export{m as __pageData,f as default};
